'use client';
import { useEffect, useId, useRef, useState, type ReactNode } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useTween } from '../lib/hooks';
import { Icon, type IconName } from '../lib/icons';
import { enter, Seg, Swap, Tip } from '../lib/motion';
import '../designme.css';
import './stat-cards.css';

export interface StatCardsValue {
  /** The number in large type, which rolls to it */
  value: number;
  /** Change against the period before, in percent. Its chip is green when the change is good news and red when it isn't
      (see `lowerIsBetter`) */
  change: number;
  /** The sparkline, oldest first */
  points: number[];
}

export interface StatCardsStat {
  /** Identifies the card. Defaults to its label */
  key?: string;
  icon: IconName;
  /** Like "Agent runs" */
  label: string;
  /** One entry per period, in the same order as `periods` */
  values: StatCardsValue[];
  /** Before the number, like "$" */
  prefix?: string;
  /** After the number, like "h" */
  suffix?: string;
  /** The sparkline's colour, any CSS colour. Defaults to the chart palette: the accent for the first card, then violet, green and orange */
  color?: string;
  /** For a number that is better when it falls, like spend: its chip turns green as it falls and red as it rises */
  lowerIsBetter?: boolean;
}

export interface StatCardsPeriod {
  /** The switch label, like "30 days" */
  label: string;
  /** What the change is measured against, like "vs previous 30 days": shown when you point at the change chip, and read
      after the number by screen readers */
  compare?: string;
}

export interface StatCardsProps {
  /** What the numbers are about, like "Workspace": on the left of the head, on one line with the period switch */
  title?: ReactNode;
  stats: StatCardsStat[];
  periods: StatCardsPeriod[];
  /** The period on show, by index. Leave it out to let the switch pick it */
  period?: number;
  defaultPeriod?: number;
  onPeriodChange?: (period: number) => void;
  /** The values at the bottom and top of every sparkline. Defaults to each card's own lowest and highest point */
  sparkRange?: [number, number];
  className?: string;
}

const FLAT = 'M0 30 L100 30';

function Card({ stat, index, period, compare, drawn, range }: { stat: StatCardsStat; index: number; period: number; compare?: string; drawn: boolean; range?: [number, number] }) {
  const v = stat.values[Math.min(period, stat.values.length - 1)];
  const shown = useTween(drawn ? v.value : 0, 900, 0);
  const all = stat.values.flatMap(x => x.points);
  const [lo, hi] = range ?? [Math.min(...all), Math.max(...all)];
  const d = v.points.map((y, k) => `${k === 0 ? 'M' : 'L'}${(k / Math.max(1, v.points.length - 1) * 100).toFixed(1)} ${(29 - (y - lo) / (hi - lo || 1) * 28).toFixed(1)}`).join(' ');
  const { className: entering, style } = enter(index * 70);
  // the sparkline draws in from the left as its card arrives
  const spark = useRef<SVGSVGElement>(null), gid = 'dm-scx-' + useId().replace(/:/g, '');
  useEffect(() => {
    const el = spark.current; if (!el || !el.animate || matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    const a = el.animate([{ clipPath: 'inset(-4px 100% -4px 0)' }, { clipPath: 'inset(-4px 0% -4px 0)' }], { duration: 1000, delay: 300 + index * 70, easing: 'cubic-bezier(.45,0,.2,1)', fill: 'backwards' });
    return () => a.cancel();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps
  // the chip: green when the change is good news, red when it isn't, with a true minus sign; pointing at it says what it is
  // measured against. The card isn't a button, so pointing at the card itself changes nothing
  const good = stat.lowerIsBetter ? v.change <= 0 : v.change >= 0;
  const text = (v.change > 0 ? '+' : v.change < 0 ? '\u2212' : '') + Math.abs(v.change) + '%';
  return (
    <div className={cx('dm-scx-c dm-panel', entering)} style={style}>
      <span className="dm-scx-k"><span className="dm-ic"><Icon name={stat.icon} size="xs" /></span>{stat.label}</span>
      <div className="dm-scx-v">
        <b className="dm-num">{(stat.prefix ?? '') + Math.round(shown).toLocaleString('en-US') + (stat.suffix ?? '')}</b>
        <Tip label={compare ?? ''} off={!compare || !drawn}>
          <Swap className={cx('dm-scx-d dm-num', drawn && cx('dm-tag', good ? 'dm-ok' : 'dm-bad', v.change >= 0 ? 'dm-up' : 'dm-dn'))}>{drawn ? text : ''}</Swap>
        </Tip>
        {compare && <span className="dm-scx-sr">{compare}</span>}
      </div>
      <div className="dm-scx-sp">
        {/* the line and, under it, the area down to the axis, which Clean fills with the line's colour fading to nothing */}
        <svg ref={spark} viewBox="0 0 100 30" preserveAspectRatio="none" aria-hidden="true" style={{ color: stat.color ?? `var(--dm-c${index % 6 + 1})` }}>
          <defs><linearGradient id={gid} x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="currentColor" stopOpacity=".22" /><stop offset="1" stopColor="currentColor" stopOpacity="0" /></linearGradient></defs>
          <path className="dm-ar" style={{ fill: `url(#${gid})` }} d={(drawn ? d : FLAT) + ' L100 30 L0 30 Z'} />
          <path className="dm-ln" stroke={stat.color ?? `var(--dm-c${index % 6 + 1})`} d={drawn ? d : FLAT} />
        </svg>
      </div>
    </div>
  );
}

/** A row of numbers with their change and a sparkline. Switch the period and they roll to the new values. */
export function StatCards({ title, stats, periods, period, defaultPeriod = 0, onPeriodChange, sparkRange, className }: StatCardsProps) {
  const [at, setAt] = useControllable(period, defaultPeriod, onPeriodChange);
  // the numbers roll up and the lines draw a moment after the cards come in
  const [drawn, setDrawn] = useState(false);
  useEffect(() => { const t = setTimeout(() => setDrawn(true), 200); return () => clearTimeout(t); }, []);

  return (
    <div data-dm="" className={cx('dm-scx', className)}>
      {(title != null || periods.length > 1) && (
        <div className="dm-scx-h">
          {title != null && <b className="dm-scx-t">{title}</b>}
          {periods.length > 1 && <Seg className="dm-scx-sg" label="Period" value={String(at)} onChange={v => setAt(+v)} options={periods.map((p, i) => ({ value: String(i), label: p.label }))} />}
        </div>
      )}
      <div className="dm-scx-grid">
        {stats.map((s, i) => <Card key={s.key ?? s.label} stat={s} index={i} period={at} compare={periods[at]?.compare} drawn={drawn} range={sparkRange} />)}
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Stat cards ---------- */
/* a row of headline numbers, each with its change against the period before and a sparkline in the chart palette. The cards
   aren't buttons, so a pointer over them changes nothing; the change chip says what it is measured against when you point
   at it */
.dm-scx{display:flex;flex-direction:column;gap:10px;width:100%}
/* the head: what the numbers are about on the left, on one line with the period switch (owner, 27 Nov: the switch alone
   left a bare bar over the cards) */
.dm-scx-h{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-3)}
.dm-scx-t{min-width:0;font-size:14px;line-height:20px;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* the card is wide in the library, and the four figures take more of its row, so each is bigger and the whole sits balanced */
.dm-card.dm-wide .dm-stage-in:has(>.dm-scx){max-width:960px}
.dm-scx-sg button{font-size:12px;height:26px;padding:0 10px}
.dm-scx-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
@media (max-width:820px){.dm-scx-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
/* phones keep two columns, two rows, with the cards' 16px insets, and the change chip goes under the number when it can't fit
   beside it */
@media (max-width:520px){.dm-scx-grid{gap:var(--dm-s-2)}.dm-scx-v{flex-wrap:wrap;row-gap:var(--dm-s-1)}.dm-scx-sp{height:28px}}
.dm-scx-c{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:6px;min-width:0}
.dm-scx-k{display:flex;align-items:center;gap:6px;font-size:12.5px;line-height:18px;color:var(--dm-muted)}
.dm-scx-k .dm-ic{display:grid;color:var(--dm-fg2)}
.dm-scx-v{display:flex;align-items:center;gap:var(--dm-s-2)}
.dm-scx-v b{font-size:14px;line-height:20px;font-weight:500;letter-spacing:-.02em}
.dm-scx-d{font-size:12px;font-weight:500}
.dm-scx-d.dm-tag{display:inline-flex;height:20px;padding:0 6px;cursor:default}
.dm-scx-sr{position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.dm-scx-sp{height:34px;margin-top:var(--dm-s-1)}
.dm-scx-sp svg{width:100%;height:100%;overflow:visible}
.dm-scx-sp path{fill:none;stroke-width:1.75;vector-effect:non-scaling-stroke;stroke-linejoin:round;transition:d .8s var(--dm-ease)}
/* the area under a line, which only Clean draws */
.dm-scx-sp path.dm-ar{display:none;stroke:none}
/* Clean (owner, 17 and 18 Nov): each card's content 16px in from every edge */
:root[data-style="clean"] .dm-scx-c.dm-panel,:root [data-style="clean"] .dm-scx-c.dm-panel,:root [data-style="clean"].dm-scx-c.dm-panel{padding:16px}
/* Clean (owner, 21 Nov: "design something custom because apart from the switcher and the shape of the containers there's no
   difference between Soft and Clean"): one panel instead of four cards. The period switch sits in its off-white head strip
   under a hairline; under it the figures are cells of one grid, split by half-strength hairlines (the grid's 1px gaps), each
   with its label, figure and change chip (a status chip) on the same lines as its neighbours', 16px in. The sparklines keep
   the chart palette, as Soft's do (the first in the accent, white in dark through its token, then --dm-c2 to --dm-c4): thin lines
   with straight segments and sharp corners, the area under each fading from its line's colour to nothing */
:root[data-style="clean"] .dm-scx,:root [data-style="clean"] .dm-scx,:root [data-style="clean"].dm-scx{gap:0;background:var(--dm-surface);border-radius:var(--dm-r-card);box-shadow:var(--dm-shadow);overflow:hidden}
:root[data-style="clean"] .dm-scx-h,:root [data-style="clean"] .dm-scx-h,:root [data-style="clean"].dm-scx-h{align-items:center;min-height:48px;padding:var(--dm-strip-y) 16px;background:var(--dm-strip);border-bottom:1px solid var(--dm-line)}
:root[data-style="clean"] .dm-scx>.dm-scx-grid,:root [data-style="clean"] .dm-scx>.dm-scx-grid,:root [data-style="clean"].dm-scx>.dm-scx-grid{gap:1px;background:color-mix(in srgb,var(--dm-line) 50%,var(--dm-surface))}
:root[data-style="clean"] .dm-scx>.dm-scx-grid>.dm-scx-c.dm-panel,:root [data-style="clean"] .dm-scx>.dm-scx-grid>.dm-scx-c.dm-panel,:root [data-style="clean"].dm-scx>.dm-scx-grid>.dm-scx-c.dm-panel{background:var(--dm-surface);border-radius:0;box-shadow:none}
:root[data-style="clean"] .dm-scx-sp path.dm-ln,:root [data-style="clean"] .dm-scx-sp path.dm-ln,:root [data-style="clean"].dm-scx-sp path.dm-ln{stroke-width:1.25;stroke-linejoin:miter}
:root[data-style="clean"] .dm-scx-sp path.dm-ar,:root [data-style="clean"] .dm-scx-sp path.dm-ar,:root [data-style="clean"].dm-scx-sp path.dm-ar{display:inline}

